module med21 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [7:0] w0;
  reg [7:0] w1;
  reg [7:0] w2;
  reg [7:0] w3;
  reg [7:0] w4;
  reg [7:0] w5;
  reg [7:0] w6;
  reg [7:0] w7;
  reg [7:0] w8;
  reg [7:0] w9;
  reg [7:0] w10;
  reg [7:0] w11;
  reg [7:0] w12;
  reg [7:0] w13;
  reg [7:0] w14;
  reg [7:0] w15;
  reg [7:0] w16;
  reg [7:0] w17;
  reg [7:0] w18;
  reg [7:0] w19;
  reg [7:0] w20;
  wire [7:0] samples [0:20];
  integer i, j, mid;
  reg [7:0] temp;
  always @(posedge clk) begin
    if (!rst_n) begin
      y<=0; w0<=0; w1<=0; w2<=0; w3<=0; w4<=0; w5<=0; w6<=0; w7<=0; w8<=0; w9<=0; w10<=0; w11<=0; w12<=0; w13<=0; w14<=0; w15<=0; w16<=0; w17<=0; w18<=0; w19<=0; w20<=0;
    end else begin
      samples[0] = x;
      for (i = 1; i < 21; i = i + 1) samples[i] = w0;
      for (i = 0; i < 20; i = i + 1)
      for (j = 0; j < 20 - i; j = j + 1)
        if (samples[j] > samples[j+1]) begin
          temp = samples[j];
          samples[j] = samples[j+1];
          samples[j+1] = temp;
        end
      mid = (21 - 1) / 2;
      if (21 % 2 == 0) y <= {8'b0, samples[mid]};
      else y <= {8'b0, (samples[mid] + samples[mid+1]) / 2};
      w20 <= w19; w19 <= w18; w18 <= w17; w17 <= w16; w16 <= w15; w15 <= w14; w14 <= w13; w13 <= w12; w12 <= w11; w11 <= w10; w10 <= w9; w9 <= w8; w8 <= w7; w7 <= w6; w6 <= w5; w5 <= w4; w4 <= w3; w3 <= w2; w2 <= w1; w1 <= w0; w0 <= x;
    end
  end
endmodule

